feed:
  {{ site.name }}
  {{ site.description }}


{# The feed's own durable identity — frozen in masthead.json, never derived.
   RFC 4287 §4.2.6 makes atom:id a permanent, universally unique identifier for
   the feed; the address it is served at is `rel="self"` just above, and that is
   the one that moves. Deriving this from canonical_url made the two the same
   string, so rehosting silently reissued the feed's identity along with its
   address — a subscriber can reasonably read that as a different feed.

   This is the object-level rule of PROTOCOL.md §8.1 applied one level up:
   feed identity is carried, not reissued. #}
  {{ site.feed_guid }}
{# Who publishes this publication. Atom has carried a URI for its author
   since RFC 4287 §3.2.2 and these feeds simply never emitted one, so a
   consumer could read the name and had no way to reach the person. The URI
   is the identity (PROTOCOL.md §2 `publishers`), and it is the half of
   reciprocal verification a reader checks against the identity's own claim.

   Decision record: reports/2026-08-17-commons-identity-publication-relation-audit.md.
   Nothing here is a Commons invention — `atom:author/atom:uri` already means
   exactly this, and a feed reader that ignores it is unaffected.

   `site.author` remains as the display name when no publishers are declared,
   so a publication that has not adopted the relationship is unchanged. -#}
{% for p in site.get('publishers', []) %}  {{ p.get('name') or p.url }}{{ p.url }}
{% endfor %}{% if not site.get('publishers') %}  {{ site.author }}
{% endif %}
{% for film in films %}

    {{ film | title_of }}

    {#- The identity, not the address.  above moves if the publication is
        rehosted; this must not. -#}
    {{ film.guid }}
    {{ film.created }}
    {% if film.description %}{{ film.description }}{% endif %}

{% endfor %}
